-- The code that makes quest `q` slow, or nil when it is not on the list.
function List.Slow(q)
	if type(q) ~= "number" then return nil end
	local key = " " .. q .. " "
	for code, ids in pairs(codes) do
		if find(ids, key, 1, true) then return code end
	end
	return nil
end

